package com.ecole.gestion_scolaire.hr.entity; import jakarta.persistence.*; @Entity @Table(name="employee_emergency_contact") public class EmployeeEmergencyContact { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="employee_id") private Employee employee; @Column(nullable=false,length=150) private String name; @Column(name="relationship",length=80) private String relationship; @Column(nullable=false,length=30) private String phone; @Column(name="secondary_phone",length=30) private String secondaryPhone; @Column(nullable=false) private boolean primaryContact; public Long getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getRelationship(){return relationship;} public void setRelationship(String v){relationship=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getSecondaryPhone(){return secondaryPhone;} public void setSecondaryPhone(String v){secondaryPhone=v;} public boolean isPrimaryContact(){return primaryContact;} public void setPrimaryContact(boolean v){primaryContact=v;} }